'use strict';
// Generated bytes only. No game executable, archive parser or original media.
// Run from the repository root. Full production WAT handlers execute in actual
// OS Workers, sharing the browser-style singleton filesystem broker.
const assert = require('node:assert/strict');
const { Worker } = require('node:worker_threads');
const { createHash } = require('node:crypto');
const path = require('node:path');
const ROOT = path.resolve(__dirname, '..'); // final home: test/
const { bootRenderHarness } = require(path.join(ROOT, 'test/render-helper'));
const RPC = require(path.join(ROOT, 'lib/guest-rpc'));
const { sigs } = require(path.join(ROOT, 'lib/host-import-sigs.generated.json'));
const apis = require(path.join(ROOT, 'src/api_table.json'));
const id = name => apis.find(api => api.name === name).id;
const extraWat = `
 (func (export "resource_setup") (param $tid i32)
  (global.set $image_base (i32.const 0x400000))
  (global.set $current_thread_id (local.get $tid))
  (global.set $reg_base (i32.add (region.addr $REGFILE 0)
    (i32.mul (local.get $tid) (global.get $REGFILE_STRIDE)))))
 (func (export "resource_call") (param $api i32)
  (param $a i32) (param $b i32) (param $c i32) (param $d i32) (param $f i32) (result i32)
  (i32.store offset=16 (global.get $reg_base) (i32.const 0x700000))
  (call $dispatch_api_table (local.get $api) (local.get $a) (local.get $b)
    (local.get $c) (local.get $d) (local.get $f) (i32.const 0))
  (i32.load (global.get $reg_base)))
 (func (export "resource_map") (param $ga i32) (result i32)
  (call $virtual_map_commit (local.get $ga) (i32.const 4096)))
`;

(async () => {
  const h = await bootRenderHarness({ extraWat, fonts: 'none',
    tailCalls: !process.argv.includes('--compat') });
  const vfs = h.hostCtx.vfs, e = h.exports;
  // The singleton host's translator and both guest instances share a PE base.
  e.resource_setup(1);
  const size = 4206880;
  const fixture = Uint8Array.from({ length: size }, (_, i) =>
    (Math.imul(i ^ (i >>> 12), 37) + (i >>> 8) + 19) & 255);
  vfs.files.set('c:\\generated-resource.bin', { data: fixture, attrs: 0x20 });
  const handle = vfs.createFile('c:\\generated-resource.bin', 0x80000000, 3);
  const denied = vfs.createFile('c:\\generated-resource.bin', 0, 3);
  assert(handle > 0 && denied > 0);
  const calls = [], errors = [], pending = new Map(), workers = [];
  const host = { ...h.host };
  for (const name of ['fs_read_file_result', 'fs_seek_result']) {
    const original = host[name];
    host[name] = (...args) => {
      const fh = vfs.getOpenFile(args[0]), before = fh?.pos;
      const result = original(...args);
      calls.push({ name, args, before, after: fh?.pos, result });
      return result;
    };
  }
  const broker = RPC.createMainBroker(h.memory, host, sigs,
    { onError: (name, error) => errors.push([name, String(error)]) });
  let serial = 0;
  try {
    for (const slot of [1, 2]) {
      const worker = new Worker(`
        const {parentPort,workerData:d}=require('node:worker_threads');
        const rpc=require(d.rpc).createWorkerImports(d.memory,d.sigs,
          message=>parentPort.postMessage(message),{slot:d.slot});
        const imports=rpc.imports;
        // The file operations do not use the separate GDI import namespace.
        const gdi={};
        for(const imp of WebAssembly.Module.imports(d.module))
          if(imp.module==='gdi')gdi[imp.name]=()=>{throw Error('unexpected GDI call')};
        imports.gdi=gdi;
        const e=new WebAssembly.Instance(d.module,imports).exports;
        e.resource_setup(d.slot+1);
        parentPort.on('message',({id,api,args})=>{
          try {const value=e.resource_call(api,...args);
            parentPort.postMessage({id,value,error:e.test_get_last_error(),esp:e.get_esp()});}
          catch(error){parentPort.postMessage({id,failure:error.stack});}
        });
      `, { eval: true, workerData: { module: h.module, memory: h.memory,
        sigs, slot, rpc: path.join(ROOT, 'lib/guest-rpc') } });
      workers.push(worker);
      const fail = error => {
        for (const item of pending.values()) if (item.worker === worker) item.finish(error);
      };
      worker.on('error', fail);
      worker.on('exit', code => fail(Error(`resource Worker exited before reply: ${code}`)));
      worker.on('message', message => {
        if (message.t === 'rpc') broker.serveRpc(message.slot);
        else if (pending.has(message.id)) pending.get(message.id).finish(
          message.failure ? Error(message.failure) : null, message);
      });
    }
    const ask = (which, name, ...args) => new Promise((resolve, reject) => {
      const request = ++serial, worker = workers[which];
      const finish = (error, result) => {
        clearTimeout(timer); pending.delete(request); error ? reject(error) : resolve(result);
      };
      const timer = setTimeout(() => finish(Error('resource Worker reply exceeded 10 seconds')), 10000);
      pending.set(request, { worker, finish });
      worker.postMessage({ id: request, api: id(name), args: [...args, 0, 0, 0, 0, 0].slice(0, 5) });
    });
    // Both instantiations must finish before test writes touch shared memory.
    await ask(0, 'GetLastError');
    await ask(1, 'GetLastError');
    const COUNT = 0x401000, HIGH = 0x401010, BUF = 0x1000000;
    const seek = async (which, low, method = 0, high = 0, hfile = handle) => {
      const result = await ask(which, 'SetFilePointer', hfile, low, high, method);
      assert.equal(result.esp, 0x700014, 'seek stdcall frame');
      return result;
    };
    const read = async (which, count, dest = BUF, hfile = handle) => {
      e.guest_write32(COUNT, 0xdeadbeef);
      const result = await ask(which, 'ReadFile', hfile, dest, count, COUNT, 0);
      assert.equal(result.esp, 0x700018, 'read stdcall frame');
      return { ...result, count: e.guest_read32(COUNT) >>> 0 };
    };
    const bytes = (ga, n) => {
      const out = Buffer.alloc(n);
      // Use each page's production translator, including nonadjacent backing.
      for (let done = 0; done < n;) {
        const len = Math.min(n - done, 4096 - ((ga + done) & 4095));
        out.set(new Uint8Array(h.memory.buffer, e.guest_to_wasm(ga + done), len), done);
        done += len;
      }
      return out;
    };
    const hash = b => createHash('sha256').update(b).digest('hex');
    await ask(0, 'SetLastError', 23);
    const full = await read(0, size);
    assert.equal(full.value, 1); assert.equal(full.count, size); assert.equal(full.error, 23);
    assert.equal(hash(bytes(BUF, size)), hash(fixture), 'all generated bytes survived WAT/Worker/RPC');
    assert.equal(vfs.getOpenFile(handle).pos, size);
    assert.equal(calls.at(-1).args.at(-1), 2, 'adapter attaches calling instance thread ID');
    const eof = await read(0, 1);
    assert.equal(eof.value, 1); assert.equal(eof.count, 0); assert.equal(eof.error, 23);
    const tail = await seek(0, -17, 2);
    assert.equal(tail.value, size - 17); assert.equal(tail.error, 0);
    for (let i = 0; i < 32; i++) e.guest_write8(BUF + i, 0xcc);
    const short = await read(0, 32);
    assert.equal(short.value, 1); assert.equal(short.count, 17);
    assert.deepEqual(bytes(BUF, 17), Buffer.from(fixture.subarray(size - 17)));
    assert.deepEqual(bytes(BUF + 17, 15), Buffer.alloc(15, 0xcc), 'short read preserves unwritten suffix');
    const zero = await read(0, 0);
    assert.equal(zero.value, 1); assert.equal(zero.count, 0);
    assert.equal((await seek(0, -17, 1)).value, size - 17, 'FILE_CURRENT uses signed distance');
    assert.equal((await seek(0, 0, 2)).value, size);
    const bad = await seek(0, -1);
    assert.equal(bad.value, -1); assert.equal(bad.error, 131);
    assert.equal(vfs.getOpenFile(handle).pos, size, 'failed negative seek leaves cursor alone');
    const badMethod = await seek(0, 0, 3);
    assert.equal(badMethod.value, -1); assert.equal(badMethod.error, 87);
    assert.equal(vfs.getOpenFile(handle).pos, size);
    // High/low words travel in one operation, including a valid -1 low result.
    e.guest_write32(HIGH, 0);
    const sentinel = await seek(0, -1, 0, HIGH);
    assert.equal(sentinel.value, -1); assert.equal(sentinel.error, 0);
    assert.equal(e.guest_read32(HIGH), 0);
    e.guest_write32(HIGH, 1);
    assert.equal((await seek(0, 7, 0, HIGH)).value, 7);
    assert.equal(vfs.getOpenFile(handle).pos, 0x100000007);
    const beyond = await read(0, 8);
    assert.equal(beyond.value, 1); assert.equal(beyond.count, 0);
    // A real per-operation failure must replace only its caller's last error.
    const rejected = await read(1, 8, BUF, denied);
    assert.equal(rejected.value, 0); assert.equal(rejected.error, 5); assert.equal(rejected.count, 0);
    assert.equal((await ask(0, 'GetLastError')).value, 0);
    assert.equal((await ask(1, 'GetLastError')).value, 5);
    const invalid = await read(1, 8, BUF, 0xdead);
    assert.equal(invalid.value, 0); assert.equal(invalid.error, 6); assert.equal(invalid.count, 0);
    // Split mapping, deliberately interleaved backing, and a 4 MiB file offset.
    const PAGE = 0x30000000;
    for (const ga of [PAGE, 0x28000000, PAGE + 4096, PAGE + 8192])
      assert.equal(e.resource_map(ga) >>> 0, ga);
    assert.notEqual(e.guest_to_wasm(PAGE + 4095) + 1, e.guest_to_wasm(PAGE + 4096));
    const offset = 0x400000 - 5, length = 8200;
    await seek(0, offset);
    const sparse = await read(1, length, PAGE + 3);
    assert.equal(sparse.value, 1); assert.equal(sparse.count, length);
    assert.equal(sparse.error, 6, 'successful peer read preserves its own previous last error');
    assert.deepEqual(bytes(PAGE + 3, length), Buffer.from(fixture.subarray(offset, offset + length)));
    assert.equal(calls.at(-1).args.at(-1), 3);
    assert.equal(vfs.getOpenFile(handle).pos, offset + length);
    assert.deepEqual(errors, []);
    assert(calls.filter(c => c.name === 'fs_read_file_result').length >= 8);
    console.log(JSON.stringify({ outcome: 'PASS', fixtureBytes: size, fixtureSha256: hash(fixture),
      workerCalls: serial, brokerOperations: calls, compat: process.argv.includes('--compat') }));
  } finally {
    await Promise.all(workers.map(worker => worker.terminate()));
    vfs.closeAllDiskHandles();
  }
})().catch(error => { console.error(error); process.exitCode = 1; });
